/// Public download locations for the installable SmartEat apps.
///
/// These URLs are pinned to the current release version as GitHub Release
/// assets. They are regenerated by `scripts/build_downloads.ps1` whenever the
/// app version changes, so they should not be edited by hand.
class AppDownloads {
  AppDownloads._();

  static const String androidApk =
      'https://github.com/LGLabs1/SmartEat/releases/download/v1.0.3/smarteat-android-1.0.3.apk';

  static const String windowsZip =
      'https://github.com/LGLabs1/SmartEat/releases/download/v1.0.3/smarteat-windows-1.0.3.zip';
}
